// German A2 practice rooms: 6 modules x 12 rooms x 3 questions.
window.deRooms = window.deRooms || {};
deRooms.A2 = [
  // Module 1: Talking About the Past (Perfekt)
  [
    {t:"Past-time words",s:"Vocabulary",qs:[
      {q:"What does 'gestern' mean?",opts:["yesterday","tomorrow","today","last week"],a:0,ex:"'gestern' points to the day before today; 'morgen' would be tomorrow and 'heute' today."},
      {q:"Which phrase means 'last weekend'?",opts:["letztes Wochenende","nächstes Wochenende","jedes Wochenende","dieses Wochenende"],a:0,ex:"'letzt-' means last or previous; 'nächst-' means next and 'dies-' means this."},
      {q:"'Ich habe gegessen' means…",opts:["I ate","I drank","I slept","I bought"],a:0,ex:"'gegessen' is the past participle of 'essen' (to eat)."}
    ]},
    {t:"Participles & time words",s:"Vocabulary",qs:[
      {q:"Which participle belongs to the verb 'gehen'?",opts:["gegangen","gegeht","gegehen","gangen"],a:0,ex:"'gehen' is a strong verb: its stem changes and the participle ends in -en: gegangen."},
      {q:"What does 'danach' mean?",opts:["afterwards","before","during","already"],a:0,ex:"'danach' = after that; it is used to link the steps of a story in order."},
      {q:"Odd one out: which expression does NOT refer to the past?",opts:["gestern","letzte Woche","vorgestern","morgen"],a:3,ex:"'morgen' means tomorrow; the others (yesterday, last week, the day before yesterday) refer to the past."}
    ]},
    {t:"Sounds in participles",s:"Pronunciation",qs:[
      {q:"Listen. How is the prefix 'ge-' pronounced in this participle?",say:"gemacht",opts:["short and unstressed, like 'g' + 'uh'","long and stressed, like 'gay'","silent, it is not spoken","like English 'j' in 'jet'"],a:0,ex:"The participle prefix ge- is never stressed; its e is a short, weak vowel."},
      {q:"Listen. How is the 'ch' in 'gemacht' pronounced?",say:"gemacht",opts:["a throaty sound, as in Scottish 'loch'","like 'ch' in English 'church'","like 'k' in 'kite'","like 'sh' in 'shop'"],a:0,ex:"After a, o, u and au, German ch is the back 'ach' sound made in the throat."},
      {q:"Listen. Which participle do you hear?",say:"gegessen",opts:["gegessen","gesessen","vergessen","gewesen"],a:0,ex:"'gegessen' (from essen) has two g sounds; 'gesessen' comes from sitzen and 'vergessen' has no ge-."}
    ]},
    {t:"haben + participle",s:"Grammar",qs:[
      {q:"Complete: 'Ich ___ einen Film gesehen.'",opts:["habe","bin","hat","sind"],a:0,ex:"'sehen' takes haben, and with ich the form of haben is 'habe'."},
      {q:"Complete: 'Wir ___ nach Berlin gefahren.'",opts:["sind","haben","seid","hat"],a:0,ex:"'fahren' is a verb of movement, so it takes sein; with wir the form is 'sind'."},
      {q:"In a Perfekt main clause, where does the past participle go?",opts:["at the end of the clause","in position 2","right after the subject","at the very start"],a:0,ex:"haben/sein takes position 2 and the participle closes the clause: Ich habe Deutsch gelernt."}
    ]},
    {t:"haben or sein?",s:"Grammar",qs:[
      {q:"Which verb forms its Perfekt with 'sein'?",opts:["kommen","essen","kaufen","lernen"],a:0,ex:"'kommen' expresses movement from A to B, so it uses sein: Ich bin gekommen."},
      {q:"Which Perfekt sentence about going home is correct?",opts:["Sie ist nach Hause gegangen.","Sie hat nach Hause gegangen.","Sie ist nach Hause gegeht.","Sie hat nach Hause gegeht."],a:0,ex:"'gehen' takes sein, and its participle is the strong form 'gegangen'."},
      {q:"Choose the correct participle: 'Er hat das Buch ___.'",opts:["gelesen","gelest","gelesst","lesen"],a:0,ex:"'lesen' is a strong verb, so its participle ends in -en: gelesen."}
    ]},
    {t:"Reading: Tom's weekend",s:"Reading",qs:[
      {q:"Read: 'Am Samstag bin ich ins Kino gegangen. Am Sonntag habe ich meine Oma besucht.' What did Tom do on Sunday?",opts:["He visited his grandmother.","He went to the cinema.","He stayed at home.","He visited his aunt."],a:0,ex:"'Oma' means grandma, and 'besucht' is the participle of besuchen (to visit)."},
      {q:"Read: 'Gestern habe ich lange geschlafen. Danach habe ich mit Lisa Kaffee getrunken.' What happened first?",opts:["He slept late.","He drank coffee.","He met Lisa at work.","He made breakfast."],a:0,ex:"'Danach' (afterwards) shows that the coffee came after sleeping late."},
      {q:"Read: 'Letztes Wochenende sind wir an die Ostsee gefahren. Leider hat es viel geregnet.' Which statement is true?",opts:["The weather was bad.","They flew to the coast.","It was sunny all weekend.","They stayed at home."],a:0,ex:"'Leider hat es viel geregnet' = unfortunately it rained a lot, so the weather was bad."}
    ]},
    {t:"Listening: last weekend",s:"Listening",qs:[
      {q:"Listen. What did the speaker do on Saturday?",say:"Ich habe am Samstag Fußball gespielt.",opts:["played football","watched football","played tennis","went swimming"],a:0,ex:"'Fußball gespielt' is the Perfekt of 'Fußball spielen' (to play football)."},
      {q:"Listen. When did they come home?",say:"Wir sind um acht Uhr nach Hause gekommen.",opts:["at eight o'clock","at seven o'clock","at six o'clock","at nine o'clock"],a:0,ex:"'um acht Uhr' means at eight o'clock; 'nach Hause gekommen' = came home."},
      {q:"Listen. What does the speaker want to know?",say:"Hast du gestern Abend gekocht?",opts:["whether you cooked last night","whether you ate out yesterday","whether you will cook tonight","whether you bought food today"],a:0,ex:"'gestern Abend' = yesterday evening, and 'gekocht' is the participle of kochen (to cook)."}
    ]},
    {t:"Chatting about the weekend",s:"Speaking",qs:[
      {q:"A friend asks: 'Was hast du am Wochenende gemacht?' What is the best reply?",opts:["Ich habe meine Eltern besucht.","Ich besuche meine Eltern morgen.","Ja, ich habe das gemacht.","Am Wochenende ist sehr schön."],a:0,ex:"The question is in the Perfekt about the past, so you answer with a Perfekt sentence about what you did."},
      {q:"You want to ask a friend where they travelled on holiday. What do you say?",opts:["Wohin bist du gefahren?","Wohin hast du gefahren?","Wo bist du fahren?","Wohin fährst du gestern?"],a:0,ex:"'fahren' takes sein in the Perfekt, and 'wohin' asks about the destination."},
      {q:"Your colleague says: 'Ich bin gestern nach Wien geflogen.' What is a natural reaction?",opts:["Toll! Wie war der Flug?","Toll! Wann bist du fliegen?","Toll! Wie hat der Flug?","Toll! Wo hast du geflogen?"],a:0,ex:"'Wie war ...?' is the usual way to ask how something went; war is the past of sein."}
    ]},
    {t:"Writing a diary entry",s:"Writing",qs:[
      {q:"Diary entry: choose the correctly written sentence.",opts:["Gestern habe ich Pizza gegessen.","Gestern ich habe Pizza gegessen.","Gestern habe ich gegessen Pizza.","Gestern habe gegessen ich Pizza."],a:0,ex:"After a time word in position 1, the verb 'habe' comes second, then the subject; the participle goes last."},
      {q:"Fill the gap in the diary: 'Am Abend habe ich Musik ___.'",opts:["gehört","gehören","hörte gern","hören"],a:0,ex:"'hören' is regular, so the participle is ge- + hör + -t: gehört."},
      {q:"Which word order is correct for the last line of the diary?",opts:["Danach bin ich ins Bett gegangen.","Danach ich bin ins Bett gegangen.","Danach bin ich gegangen ins Bett.","Danach ich ins Bett gegangen bin."],a:0,ex:"'Danach' takes position 1, so the auxiliary 'bin' is second and the participle 'gegangen' goes to the end."}
    ]},
    {t:"The past in everyday talk",s:"Culture",qs:[
      {q:"In spoken German, which tense do people mostly use to talk about the past?",opts:["the Perfekt","the future tense","the present tense only","the Präteritum of every verb"],a:0,ex:"In conversation Germans mainly use the Perfekt; the Präteritum of most verbs is typical of written texts."},
      {q:"Which simple past form is common even in everyday speech?",opts:["ich war","ich ging","ich aß","ich fuhr"],a:0,ex:"'war' and 'hatte' (from sein and haben) are used in speech too; ging, aß, fuhr sound written or literary."},
      {q:"On Monday a German colleague asks: 'Wie war dein Wochenende?' What is expected?",opts:["a short, genuine answer","a detailed hour-by-hour report","no answer, it is just 'hello'","a question about their family"],a:0,ex:"It is friendly small talk; a brief honest reply (Gut, ich war wandern) is normal, not a ritual greeting."}
    ]},
    {t:"Review: the Perfekt",s:"Review",qs:[
      {q:"Translate: 'She drank coffee.'",opts:["Sie hat Kaffee getrunken.","Sie ist Kaffee getrunken.","Sie hat Kaffee getrinkt.","Sie hat Kaffee trinken."],a:0,ex:"'trinken' takes haben and has a strong participle with a vowel change: getrunken."},
      {q:"What is the past participle of 'machen'?",opts:["gemacht","gemachen","macht","gemachtet"],a:0,ex:"Regular verbs form the participle with ge- + stem + -t: ge-mach-t."},
      {q:"Complete: 'Zuerst habe ich gearbeitet, ___ bin ich nach Hause gefahren.'",opts:["danach","gestern","früher","letztes"],a:0,ex:"'danach' (afterwards) links the second step of the sequence and sends the verb 'bin' into position 2."}
    ]},
    {t:"Tricky participles",s:"Challenge",qs:[
      {q:"Complete: 'Ich ___ den ganzen Tag zu Hause geblieben.'",opts:["bin","habe","war","hat"],a:0,ex:"'bleiben' takes sein in the Perfekt even though there is no movement: ich bin geblieben."},
      {q:"What is the correct participle of 'studieren'?",opts:["studiert","gestudiert","studieren","gestudieret"],a:0,ex:"Verbs ending in -ieren never take ge- in the participle: studiert, telefoniert, fotografiert."},
      {q:"Which sentence with 'vergessen' is correct?",opts:["Ich habe das Wort vergessen.","Ich habe das Wort gevergessen.","Ich bin das Wort vergessen.","Ich habe das Wort vergesst."],a:0,ex:"Verbs with the inseparable prefix ver- add no ge-, and vergessen takes haben: ich habe vergessen."}
    ]}
  ],
  // Module 2: Getting Around & Asking Directions
  [
    {t:"Direction words",s:"Vocabulary",qs:[
      {q:"What does 'geradeaus' mean?",opts:["straight ahead","back","around the corner","to the left"],a:0,ex:"'geradeaus' = keep going straight; 'zurück' would be back and 'links' left."},
      {q:"'die Ampel' is…",opts:["the traffic light","the crossroads","the bus stop","the street sign"],a:0,ex:"'die Ampel' is the traffic light; a crossroads is 'die Kreuzung'."},
      {q:"Which word means 'right' as a direction?",opts:["rechts","links","richtig","rückwärts"],a:0,ex:"'rechts' is the direction right; 'richtig' means right in the sense of correct."}
    ]},
    {t:"Places & shopping words",s:"Vocabulary",qs:[
      {q:"'gegenüber' means…",opts:["opposite","next to","behind","between"],a:0,ex:"'gegenüber' = across from / opposite; next to is 'neben', between is 'zwischen'."},
      {q:"What is 'das Sonderangebot'?",opts:["the special offer","the receipt","the shop window","the price tag"],a:0,ex:"'Sonder-' means special and 'Angebot' means offer: a reduced-price deal."},
      {q:"Odd one out:",opts:["die Apotheke","die Post","der Bahnhof","die Größe"],a:3,ex:"'die Größe' means the size; the others are places in town (pharmacy, post office, station)."}
    ]},
    {t:"Sounds of directions",s:"Pronunciation",qs:[
      {q:"Listen. How is 'au' in 'geradeaus' pronounced?",say:"geradeaus",opts:["like 'ow' in 'cow'","like 'aw' in 'saw'","like 'o' in 'go'","like 'oo' in 'too'"],a:0,ex:"German au always sounds like English 'ow' in cow or how."},
      {q:"Listen. Which syllable is stressed in 'gegenüber'?",say:"gegenüber",opts:["-ü-","ge-","-gen-","-ber"],a:0,ex:"The word is stressed on the ü: gegen-Ü-ber."},
      {q:"Listen. How is the 'ch' in 'rechts' pronounced?",say:"rechts",opts:["a soft hiss, as in 'ich'","a throaty sound, as in 'Bach'","like 'k' in 'kite'","like 'ch' in 'chin'"],a:0,ex:"After e, i, ä, ö, ü and consonants, ch is the soft front 'ich' sound."}
    ]},
    {t:"zum and zur",s:"Grammar",qs:[
      {q:"Complete: 'Wie komme ich ___ Bahnhof?'",opts:["zum","zur","zu","zu den"],a:0,ex:"'zu' takes the dative; der Bahnhof becomes dem Bahnhof, and zu + dem = zum."},
      {q:"Complete: 'Wie komme ich ___ Post?'",opts:["zur","zum","zu das","zu die"],a:0,ex:"die Post is feminine; in the dative it is der Post, and zu + der = zur."},
      {q:"'zum' is a short form of…",opts:["zu dem","zu den","zu der","zu das"],a:0,ex:"zum = zu + dem (masculine or neuter dative); zur = zu + der (feminine dative)."}
    ]},
    {t:"Where? Dative for places",s:"Grammar",qs:[
      {q:"Complete: 'Die Bank ist neben ___ Apotheke.'",opts:["der","die","den","dem"],a:0,ex:"It answers 'wo?' (location), so neben takes the dative; die Apotheke becomes der Apotheke."},
      {q:"Complete: 'Das Café ist zwischen ___ Kino und der Post.'",opts:["dem","das","den","der"],a:0,ex:"Location takes the dative; das Kino becomes dem Kino after zwischen."},
      {q:"Which sentence about waiting at the light is correct?",opts:["Ich warte an der Ampel.","Ich warte an die Ampel.","Ich warte am die Ampel.","Ich warte an den Ampel."],a:0,ex:"Waiting is a location (wo?), so an + dative: die Ampel becomes an der Ampel."}
    ]},
    {t:"Reading: directions & signs",s:"Reading",qs:[
      {q:"Read: 'Geh hier geradeaus bis zur Ampel. Dann nimm die zweite Straße links. Das Museum ist gegenüber der Kirche.' Where is the museum?",opts:["opposite the church","next to the church","at the traffic light","behind the church"],a:0,ex:"'gegenüber der Kirche' = across from the church."},
      {q:"Read the sign in a shop: 'Sonderangebot: T-Shirts nur 9,99 €'. What does it tell you?",opts:["T-shirts are on special offer.","T-shirts are sold out.","T-shirts cost more today.","T-shirts come only in size M."],a:0,ex:"'Sonderangebot' = special offer and 'nur' = only, so the T-shirts are cheap."},
      {q:"Read: 'Die Apotheke ist in der Hauptstraße, zwischen der Bank und dem Supermarkt.' Which is true?",opts:["It is between the bank and the supermarket.","It is opposite the bank.","It is inside the supermarket.","It is next to the station."],a:0,ex:"'zwischen ... und ...' means between ... and ...; the dative shows location."}
    ]},
    {t:"Listening: finding the way",s:"Listening",qs:[
      {q:"Listen. Which way should you go?",say:"Gehen Sie die erste Straße rechts.",opts:["first street on the right","first street on the left","second street on the right","straight ahead"],a:0,ex:"'die erste Straße rechts' = the first street on the right."},
      {q:"Listen. Where is the station?",say:"Der Bahnhof ist gleich neben dem Hotel.",opts:["right next to the hotel","opposite the hotel","behind the hotel","far from the hotel"],a:0,ex:"'gleich neben' = right next to; 'gegenüber' would be opposite."},
      {q:"Listen. How much does the jacket cost?",say:"Die Jacke kostet neunundvierzig Euro.",opts:["49 euros","94 euros","39 euros","59 euros"],a:0,ex:"German says the units first: neun-und-vierzig = nine and forty = 49."}
    ]},
    {t:"Asking the way & shopping",s:"Speaking",qs:[
      {q:"You are lost and want to go to the market. What do you ask a passer-by?",opts:["Entschuldigung, wie komme ich zum Markt?","Entschuldigung, wo komme ich den Markt?","Entschuldigung, wie gehe ich der Markt?","Entschuldigung, wohin ist der Markt?"],a:0,ex:"The fixed pattern is 'Wie komme ich zu + dative?'; der Markt becomes zum Markt."},
      {q:"In a clothes shop you want a T-shirt in size S. What do you say?",opts:["Haben Sie das in Größe S?","Haben Sie das bei Größe S?","Sind Sie das in Größe S?","Haben Sie das zu Größe S?"],a:0,ex:"Sizes go with 'in': Haben Sie das in Größe ...? is the standard shop question."},
      {q:"A tourist asks you: 'Wo ist die Post?' It is straight ahead. What do you say?",opts:["Gehen Sie immer geradeaus.","Gehen Sie immer zurück.","Kommen Sie immer gerade.","Gehen Sie Sie geradeaus."],a:0,ex:"The formal imperative is verb + Sie: 'Gehen Sie ...'; 'immer geradeaus' = keep going straight."}
    ]},
    {t:"Writing directions",s:"Writing",qs:[
      {q:"Directions to your home: choose the correctly written sentence.",opts:["Nehmen Sie die zweite Straße links.","Nehmen Sie die zweiten Straße links.","Nehmen Sie der zweite Straße links.","Nehmen Sie die zweites Straße links."],a:0,ex:"After 'die' (feminine accusative) the ordinal ends in -e: die zweite Straße."},
      {q:"Fill the gap: 'Mein Haus ist ___ dem Park.'",opts:["neben","nach","zu","bis"],a:0,ex:"'neben' describes a location (next to); nach, zu and bis express movement towards a place."},
      {q:"Put in order: dann / Sie / links / gehen",opts:["Dann gehen Sie links.","Dann Sie gehen links.","Dann links Sie gehen.","Gehen dann Sie links."],a:0,ex:"'Dann' fills position 1, so the verb 'gehen' must come second, followed by the subject 'Sie'."}
    ]},
    {t:"Shops & streets in Germany",s:"Culture",qs:[
      {q:"In Germany, on Sundays most shops…",opts:["are closed","open late","have lower prices","sell only food"],a:0,ex:"Shop-opening laws keep most shops closed on Sundays; only some stations, bakeries or petrol stations open."},
      {q:"At a red pedestrian light ('Ampel') in Germany, people are generally expected to…",opts:["wait, even if the road is empty","cross quickly if no car comes","ask a police officer first","cross only with a group"],a:0,ex:"Crossing at red is an offence and frowned upon, especially in front of children."},
      {q:"When you pay, the cashier asks: 'Haben Sie es passend?' What does it mean?",opts:["Do you have the exact amount?","Does it fit you well?","Do you need a bag?","Do you have a loyalty card?"],a:0,ex:"'passend' here means the exact money, so the cashier does not need to give change."}
    ]},
    {t:"Review: around town",s:"Review",qs:[
      {q:"Translate: 'The bank is next to the pharmacy.'",opts:["Die Bank ist neben der Apotheke.","Die Bank ist neben die Apotheke.","Die Bank ist neben dem Apotheke.","Die Bank ist gegen der Apotheke."],a:0,ex:"Location takes the dative and Apotheke is feminine, so: neben der Apotheke."},
      {q:"What does 'Wie komme ich zum Bahnhof?' mean?",opts:["How do I get to the station?","Where is the next station?","When does the train come?","Can I walk to the station?"],a:0,ex:"'Wie komme ich zu ...?' is the standard way to ask for directions to a place."},
      {q:"Which ordinal fits? 'Nehmen Sie die ___ Straße rechts.' (3rd)",opts:["dritte","dreite","dritten","drei"],a:0,ex:"The ordinal of drei is irregular: dritt-, and after 'die' it ends in -e: die dritte Straße."}
    ]},
    {t:"Wo? or wohin?",s:"Challenge",qs:[
      {q:"Complete (movement): 'Ich gehe in ___ Supermarkt.'",opts:["den","dem","der","das"],a:0,ex:"Movement towards (wohin?) puts in into the accusative; der Supermarkt becomes den Supermarkt."},
      {q:"Complete (location): 'Ich bin in ___ Supermarkt.'",opts:["dem","den","die","das"],a:0,ex:"Being somewhere (wo?) takes the dative; der Supermarkt becomes dem Supermarkt (= im)."},
      {q:"Which sentence describes a location (wo?) rather than a movement?",opts:["Das Buch liegt auf dem Tisch.","Ich lege das Buch auf den Tisch.","Ich gehe auf den Markt.","Er fährt in die Stadt."],a:0,ex:"'liegt auf dem Tisch' describes where something is (dative); the others show movement (accusative)."}
    ]}
  ],
  // Module 3: Separable Verbs & Modal Verbs
  [
    {t:"Everyday separable verbs",s:"Vocabulary",qs:[
      {q:"What does 'anrufen' mean?",opts:["to phone","to arrive","to answer","to listen"],a:0,ex:"'anrufen' = to call someone on the phone; to arrive is 'ankommen'."},
      {q:"'einkaufen' means…",opts:["to go shopping","to pay","to invite","to sell"],a:0,ex:"'einkaufen' = to do the shopping; to sell is 'verkaufen', to invite is 'einladen'."},
      {q:"What is 'der Termin'?",opts:["the appointment","the waiting room","the timetable","the receipt"],a:0,ex:"'der Termin' is a fixed appointment, e.g. at the doctor's or the hairdresser's."}
    ]},
    {t:"Modal verb meanings",s:"Vocabulary",qs:[
      {q:"Which modal verb means 'must / have to'?",opts:["müssen","dürfen","können","wollen"],a:0,ex:"'müssen' expresses necessity; dürfen = may, können = can, wollen = want to."},
      {q:"'dürfen' means…",opts:["to be allowed to","to have to","to want to","to be able to"],a:0,ex:"'dürfen' is about permission: Darf ich hier parken? = May I park here?"},
      {q:"Which of these verbs is separable?",opts:["aufstehen","verstehen","bekommen","besuchen"],a:0,ex:"auf- is a separable prefix (Ich stehe auf); ver- and be- are inseparable."}
    ]},
    {t:"Stress on the prefix",s:"Pronunciation",qs:[
      {q:"Listen. Where is the stress in 'anrufen'?",say:"anrufen",opts:["on 'an-'","on '-ru-'","on '-fen'","evenly on every syllable"],a:0,ex:"Separable prefixes are always stressed: AN-rufen, EIN-kaufen, AUF-stehen."},
      {q:"Listen. This verb is stressed on its first syllable. Which one is it?",say:"einkaufen",opts:["einkaufen","verkaufen","bezahlen","erzählen"],a:0,ex:"Only separable verbs stress the prefix; ver-, be- and er- are unstressed inseparable prefixes."},
      {q:"Listen. How is the 'ü' in 'müssen' pronounced?",say:"müssen",opts:["like 'i' said with rounded lips","like 'u' in 'but'","like 'oo' in 'food'","like 'ee' in 'see'"],a:0,ex:"For ü, say an i sound and round your lips; it is short in müssen because of the double s."}
    ]},
    {t:"The prefix goes to the end",s:"Grammar",qs:[
      {q:"Complete: 'Ich rufe dich morgen ___.'",opts:["an","auf","ein","mit"],a:0,ex:"The verb is anrufen; in a main clause the prefix 'an' splits off and goes to the end."},
      {q:"Which sentence about Saturday shopping is correct?",opts:["Ich kaufe am Samstag ein.","Ich einkaufe am Samstag.","Ich kaufe ein am Samstag.","Ich am Samstag einkaufe."],a:0,ex:"The verb part 'kaufe' is in position 2 and the prefix 'ein' closes the clause."},
      {q:"Complete: 'Du ___ jetzt gehen.'",opts:["musst","muss","müsst","müssen"],a:0,ex:"müssen with du is 'musst' (no umlaut in the singular); the infinitive 'gehen' goes to the end."}
    ]},
    {t:"Modals + infinitive",s:"Grammar",qs:[
      {q:"Which sentence with 'können' is correct?",opts:["Wir können Deutsch sprechen.","Wir können sprechen Deutsch.","Wir können Deutsch gesprochen.","Wir kann Deutsch sprechen."],a:0,ex:"The modal is conjugated in position 2 and the infinitive 'sprechen' goes to the end."},
      {q:"Complete: 'Ich muss morgen früh ___.'",opts:["aufstehen","stehe auf","aufgestanden","stehen auf"],a:0,ex:"After a modal, a separable verb stays in one piece as an infinitive at the end: aufstehen."},
      {q:"Complete: 'Er ___ heute nicht kommen, er ist krank.'",opts:["kann","können","kannst","könnt"],a:0,ex:"With er/sie/es, modals have no ending: er kann, er muss, er darf."}
    ]},
    {t:"Reading: a text message",s:"Reading",qs:[
      {q:"Read: 'Hi Jan, ich kann heute nicht zum Training kommen. Ich muss meiner Mutter helfen. Bis Donnerstag! Eva' Why can't Eva come?",opts:["She has to help her mother.","She is ill today.","She has training on Thursday.","She wants to visit her mother."],a:0,ex:"'Ich muss meiner Mutter helfen' = I have to help my mother; müssen shows obligation."},
      {q:"Read: 'Ihr Termin beim Zahnarzt ist am Dienstag um 9:30 Uhr. Bitte kommen Sie zehn Minuten früher.' When should you arrive?",opts:["at 9:20","at 9:30","at 9:10","at 9:40"],a:0,ex:"'zehn Minuten früher' = ten minutes earlier than 9:30, so 9:20."},
      {q:"Read the sign: 'Hier darf man nicht rauchen.' What does it say?",opts:["Smoking is not allowed here.","You don't have to smoke here.","Smoking is only allowed here.","You can buy cigarettes here."],a:0,ex:"'nicht dürfen' = not allowed; 'nicht müssen' would mean you don't have to."}
    ]},
    {t:"Listening: making plans",s:"Listening",qs:[
      {q:"Listen. What will the speaker do?",say:"Ich rufe dich heute Abend an.",opts:["call you this evening","visit you this evening","call you tomorrow morning","write to you tonight"],a:0,ex:"'rufe ... an' is the split form of anrufen (to phone); 'heute Abend' = this evening."},
      {q:"Listen. What is the receptionist suggesting?",say:"Passt Ihnen Dienstag um zehn Uhr?",opts:["Tuesday at ten","Thursday at ten","Tuesday at two","Wednesday at ten"],a:0,ex:"'Dienstag' = Tuesday (Donnerstag is Thursday) and 'zehn Uhr' = ten o'clock."},
      {q:"Listen. What do they have to do on Friday?",say:"Wir müssen am Freitag früh aufstehen.",opts:["get up early","go shopping early","stay up late","start work late"],a:0,ex:"'müssen' = have to, and 'früh aufstehen' = to get up early."}
    ]},
    {t:"Making an appointment",s:"Speaking",qs:[
      {q:"The receptionist asks: 'Passt Ihnen Dienstag?' You can't come on Tuesday. You say:",opts:["Leider nicht. Geht auch Mittwoch?","Ja, Dienstag passt mir gut.","Leider nicht. Ich passe Dienstag.","Nein, ich bin am Dienstag."],a:0,ex:"Decline politely with 'leider nicht' and suggest another day with 'Geht auch ...?'."},
      {q:"In a café you want a coffee. What is the most polite way to order?",opts:["Ich möchte einen Kaffee, bitte.","Ich will einen Kaffee, bitte.","Ich muss einen Kaffee, bitte.","Ich darf einen Kaffee, bitte."],a:0,ex:"'möchte' (would like) is the polite form; 'will' sounds demanding when ordering."},
      {q:"A friend asks: 'Kannst du mir morgen helfen?' You can. You say:",opts:["Ja, klar, ich kann dir helfen.","Ja, klar, ich kann dir geholfen.","Ja, klar, ich helfe dir können.","Ja, klar, ich kann dir hilfst."],a:0,ex:"After the modal 'kann' the main verb stays as an infinitive at the end: helfen."}
    ]},
    {t:"Writing your week",s:"Writing",qs:[
      {q:"Weekly plan: choose the correct sentence.",opts:["Am Montag kaufe ich ein.","Am Montag ich kaufe ein.","Am Montag einkaufe ich.","Am Montag kaufe ein ich."],a:0,ex:"Time first, then verb in position 2, then subject; the prefix ein goes to the end."},
      {q:"Fill the gap: 'Ich habe dich gestern ___.'",opts:["angerufen","angeruft","geanrufen","anrufen"],a:0,ex:"Separable verbs put ge- between prefix and stem: an-ge-rufen."},
      {q:"Which 'dass' sentence is correct?",opts:["Ich weiß, dass du morgen anrufst.","Ich weiß, dass du rufst morgen an.","Ich weiß, dass du morgen rufst an.","Ich weiß, dass du anrufst morgen."],a:0,ex:"In a subordinate clause the separable verb stays together and goes to the very end: anrufst."}
    ]},
    {t:"Appointments & time",s:"Culture",qs:[
      {q:"You will be 15 minutes late for a doctor's appointment in Germany. What is expected?",opts:["Call ahead and let them know.","Just arrive late, it's normal.","Arrive late and say nothing.","Skip it and don't cancel."],a:0,ex:"Punctuality matters for Termine; if you are late, a short call beforehand is the polite norm."},
      {q:"Your appointment is 'um 14 Uhr'. When is that?",opts:["2 p.m.","4 p.m.","2 a.m.","12 p.m."],a:0,ex:"Germany uses the 24-hour clock for appointments and timetables: 14 Uhr = 2 p.m."},
      {q:"Which is a polite way to cancel an appointment?",opts:["Ich muss den Termin leider absagen.","Ich will den Termin nicht mehr.","Ich darf den Termin absagen.","Ich kann den Termin leider absagt."],a:0,ex:"'leider' (unfortunately) softens it, and 'absagen' is the verb for cancelling."}
    ]},
    {t:"Review: verbs in pieces",s:"Review",qs:[
      {q:"Translate: 'I will call you tomorrow.'",opts:["Ich rufe dich morgen an.","Ich anrufe dich morgen.","Ich rufe dich an morgen.","Ich rufe an dich morgen."],a:0,ex:"German often uses the present for the future; the prefix 'an' goes to the very end."},
      {q:"Which modal fits? 'Hier ___ man nicht schwimmen. Es ist gefährlich.'",opts:["darf","will","mag","möchte"],a:0,ex:"'nicht dürfen' expresses a ban: you are not allowed to swim here."},
      {q:"What does 'Passt Ihnen Dienstag?' mean?",opts:["Does Tuesday suit you?","Are you coming on Tuesday?","Did Tuesday work for you?","Do you pay on Tuesday?"],a:0,ex:"'passen' + dative means to suit someone; it is a polite way to propose a day."}
    ]},
    {t:"Modals & prefixes combined",s:"Challenge",qs:[
      {q:"Choose the correct Perfekt of 'Wir kaufen gestern ein': 'Wir ___ gestern ___.'",opts:["haben … eingekauft","haben … geeinkauft","sind … eingekauft","haben … einkaufen"],a:0,ex:"einkaufen takes haben; the ge- goes after the prefix: ein-ge-kauft."},
      {q:"Complete: 'Ich ___ morgen nicht kommen, weil ich arbeiten ___.'",opts:["kann … muss","kann … müssen","können … muss","kann … musse"],a:0,ex:"Both modals agree with ich (kann, muss); after weil the conjugated verb goes to the end."},
      {q:"The doctor told you to rest. You report: 'Der Arzt sagt, ich ___ mich ausruhen.'",opts:["soll","will","darf","mag"],a:0,ex:"'sollen' passes on an instruction from someone else: the doctor says I should rest."}
    ]}
  ],
  // Module 4: Stories, Weather & Context
  [
    {t:"Weather words",s:"Vocabulary",qs:[
      {q:"'Es schneit' means…",opts:["It's snowing.","It's raining.","It's windy.","It's foggy."],a:0,ex:"'schneien' = to snow (der Schnee = snow); raining would be 'Es regnet'."},
      {q:"Which word means 'cloudy'?",opts:["bewölkt","sonnig","neblig","windig"],a:0,ex:"'bewölkt' comes from 'die Wolke' (cloud); sonnig = sunny, neblig = foggy."},
      {q:"What is 'der Herbst'?",opts:["autumn","spring","summer","winter"],a:0,ex:"The seasons: der Frühling, der Sommer, der Herbst, der Winter."}
    ]},
    {t:"Seasons & story words",s:"Vocabulary",qs:[
      {q:"Which season comes after winter?",opts:["der Frühling","der Herbst","der Sommer","das Jahr"],a:0,ex:"Spring (der Frühling) follows winter; 'das Jahr' is the year."},
      {q:"'plötzlich' means…",opts:["suddenly","finally","slowly","usually"],a:0,ex:"'plötzlich' marks a sudden turn in a story: Plötzlich hat es geregnet."},
      {q:"What is the opposite of 'warm'?",opts:["kalt","heiß","sonnig","nass"],a:0,ex:"'kalt' (cold) is the opposite of warm; 'heiß' means hot."}
    ]},
    {t:"Weather sounds",s:"Pronunciation",qs:[
      {q:"Listen. Which word do you hear?",say:"bewölkt",opts:["bewölkt","bewohnt","gewollt","bewegt"],a:0,ex:"'bewölkt' has the rounded ö sound followed by -lkt."},
      {q:"Listen. In 'Frühling', what does the 'h' after 'ü' do?",say:"Frühling",opts:["it is silent and makes the ü long","it is pronounced like English h","it makes the ü short","it sounds like German 'ch'"],a:0,ex:"An h after a vowel is not spoken; it marks the vowel as long."},
      {q:"Listen. How is 'ei' in 'schneit' pronounced?",say:"Es schneit.",opts:["like 'eye'","like 'ay' in 'day'","like 'ee' in 'see'","like 'e' in 'bed'"],a:0,ex:"German ei always sounds like English 'eye'; ie is the long ee sound."}
    ]},
    {t:"Weather with 'es'; war/hatte",s:"Grammar",qs:[
      {q:"Complete: '___ regnet schon den ganzen Tag.'",opts:["Es","Er","Sie","Man"],a:0,ex:"Weather verbs always use the impersonal subject 'es': es regnet, es schneit."},
      {q:"Complete: 'Gestern ___ das Wetter schön.'",opts:["war","ist","hatte","wird"],a:0,ex:"'gestern' needs a past form; for sein the Präteritum 'war' is normal even in speech."},
      {q:"Complete: 'Letzten Sommer ___ wir viel Glück mit dem Wetter.'",opts:["hatten","waren","hattet","hatte"],a:0,ex:"'Glück haben' = to be lucky; the Präteritum of haben with wir is 'hatten'."}
    ]},
    {t:"weil, dass & sequencing",s:"Grammar",qs:[
      {q:"Choose the correct ending: 'Ich bleibe zu Hause, weil …'",opts:["es regnet.","regnet es.","es hat regnet.","es regnen."],a:0,ex:"After 'weil' the conjugated verb goes to the end of the clause: weil es regnet."},
      {q:"Which sentence with 'dass' is correct?",opts:["Ich glaube, dass es morgen schneit.","Ich glaube, dass es schneit morgen.","Ich glaube, dass schneit es morgen.","Ich glaube, dass es morgen schneien."],a:0,ex:"'dass' sends the conjugated verb to the end, and with es it must be 'schneit'."},
      {q:"Complete: 'Zuerst habe ich gefrühstückt, dann ___ ich zur Arbeit gegangen.'",opts:["bin","habe","war","hat"],a:0,ex:"'gehen' takes sein in the Perfekt, and after 'dann' the auxiliary stays in position 2."}
    ]},
    {t:"Reading: a short story",s:"Reading",qs:[
      {q:"Read: 'Es war ein kalter Tag. Zuerst ist Anna zum Bäcker gegangen. Dann hat sie im Park einen Hund gesehen.' What did Anna do first?",opts:["She went to the baker's.","She saw a dog.","She went to the park.","She bought a dog."],a:0,ex:"'Zuerst' (first) introduces the trip to the baker's; 'dann' introduces the dog."},
      {q:"Read: 'Plötzlich hat es angefangen zu regnen, und wir hatten keinen Schirm.' What was the problem?",opts:["They had no umbrella.","They had no money.","It suddenly snowed.","They lost their way."],a:0,ex:"'keinen Schirm' = no umbrella; 'hatten' is the past of haben."},
      {q:"Read the forecast: 'Morgen: im Norden bewölkt, im Süden sonnig, 18 Grad.' Which is true?",opts:["It will be sunny in the south.","It will rain in the north.","It will be sunny everywhere.","It will be 8 degrees."],a:0,ex:"'im Süden sonnig' = sunny in the south; the north will only be cloudy, not rainy."}
    ]},
    {t:"Listening: weather & reasons",s:"Listening",qs:[
      {q:"Listen. What is the weather like today?",say:"Heute ist es windig und kühl, nur zwölf Grad.",opts:["windy and cool","sunny and warm","rainy and cold","windy and hot"],a:0,ex:"'windig' = windy and 'kühl' = cool; twelve degrees is not hot."},
      {q:"Listen. Why did they stay at home?",say:"Wir sind zu Hause geblieben, weil es geschneit hat.",opts:["because it snowed","because it rained","because they were ill","because it was hot"],a:0,ex:"'weil es geschneit hat' = because it snowed; geschneit is the participle of schneien."},
      {q:"Listen. When does it often rain here?",say:"Im Herbst regnet es hier oft.",opts:["in autumn","in spring","in summer","in winter"],a:0,ex:"'im Herbst' = in autumn; seasons take 'im' (in + dem)."}
    ]},
    {t:"Weather small talk",s:"Speaking",qs:[
      {q:"A neighbour says: 'Heute ist es aber heiß!' What is a natural reply?",opts:["Ja, wirklich! Mir ist auch heiß.","Ja, wirklich! Ich bin auch heiß.","Ja, wirklich! Es ist sehr kalt.","Ja, wirklich! Es hat geschneit."],a:0,ex:"To say you feel hot use the dative 'Mir ist heiß'; 'Ich bin heiß' means something quite different."},
      {q:"Your friend asks: 'Warum bist du nicht gekommen?' What is the best answer?",opts:["Weil ich krank war.","Weil ich war krank.","Denn ich krank war.","Weil war ich krank."],a:0,ex:"After 'weil' the verb goes to the end; 'denn' would keep normal word order (denn ich war krank)."},
      {q:"You begin telling a story about your day. Which sentence fits best as the FIRST one?",opts:["Zuerst sind wir ins Café gegangen.","Schließlich sind wir ins Café gegangen.","Zum Schluss sind wir ins Café gegangen.","Danach sind wir ins Café gegangen."],a:0,ex:"'Zuerst' (first) opens a sequence; schließlich and zum Schluss end it, danach continues it."}
    ]},
    {t:"Writing a short story",s:"Writing",qs:[
      {q:"Story writing: choose the correct sentence.",opts:["Danach haben wir einen Film gesehen.","Danach wir haben einen Film gesehen.","Danach haben wir gesehen einen Film.","Danach wir einen Film gesehen haben."],a:0,ex:"With 'Danach' in position 1, the auxiliary comes second and the participle goes to the end."},
      {q:"Fill the gap: 'Gestern ___ ich keine Zeit, weil ich arbeiten musste.'",opts:["hatte","war","habe","hat"],a:0,ex:"'Zeit haben' needs haben, and for the past the Präteritum 'hatte' is common: ich hatte keine Zeit."},
      {q:"Which sentence is correctly punctuated?",opts:["Ich hoffe, dass morgen die Sonne scheint.","Ich hoffe dass, morgen die Sonne scheint.","Ich hoffe dass morgen, die Sonne scheint.","Ich hoffe, dass morgen die Sonne, scheint."],a:0,ex:"German always puts a comma before a subordinate clause, i.e. directly before 'dass'."}
    ]},
    {t:"Weather in German life",s:"Culture",qs:[
      {q:"Where in Germany does it usually snow most in winter?",opts:["in the Alps in the south","on the North Sea coast","in the port of Hamburg","on the island of Sylt"],a:0,ex:"The Bavarian Alps are high and inland, so they get by far the most snow."},
      {q:"In Germany, temperatures in the weather forecast are given in…",opts:["degrees Celsius","degrees Fahrenheit","Kelvin","Réaumur"],a:0,ex:"Germany uses Celsius: 'zwanzig Grad' means 20 °C, a pleasant warm day."},
      {q:"A German saying goes: 'Es gibt kein schlechtes Wetter, nur schlechte Kleidung.' What does it mean?",opts:["Dress well and go out anyway.","Bad weather ruins clothes.","Only buy clothes when sunny.","Stay inside when it rains."],a:0,ex:"The saying means weather is no excuse: with the right clothes you can be outdoors."}
    ]},
    {t:"Review: weather & stories",s:"Review",qs:[
      {q:"Translate: 'It is cold and windy.'",opts:["Es ist kalt und windig.","Er ist kalt und windig.","Es hat kalt und windig.","Es ist kalt und Wind."],a:0,ex:"Weather uses 'es ist' + adjective; windig is the adjective, der Wind the noun."},
      {q:"Put the story words in order from first to last.",opts:["zuerst – dann – danach – schließlich","dann – zuerst – schließlich – danach","schließlich – danach – dann – zuerst","danach – zuerst – dann – schließlich"],a:0,ex:"zuerst (first), dann (then), danach (after that), schließlich (finally)."},
      {q:"Complete: 'Der ___ Wind kommt aus dem Norden.'",opts:["kalte","kalter","kalten","kaltes"],a:0,ex:"After 'der' in the nominative, the adjective simply ends in -e: der kalte Wind."}
    ]},
    {t:"Adjective endings & clauses",s:"Challenge",qs:[
      {q:"Complete: 'Es war ein ___ Tag.'",opts:["kalter","kalte","kaltes","kalten"],a:0,ex:"'ein' does not show the gender, so the adjective takes it: masculine nominative -er (ein kalter Tag)."},
      {q:"Choose the correct sentence about yesterday.",opts:["Ich weiß, dass er gestern krank war.","Ich weiß, dass er war gestern krank.","Ich weiß, dass er gestern war krank.","Ich weiß, dass war er gestern krank."],a:0,ex:"In a dass-clause the conjugated verb 'war' must stand at the very end."},
      {q:"Complete: 'Ich habe ein ___ Buch gelesen.'",opts:["spannendes","spannende","spannender","spannenden"],a:0,ex:"After 'ein' with a neuter noun (das Buch) in the accusative, the adjective ends in -es."}
    ]}
  ],
  // Module 5: Emails, Travel & Review
  [
    {t:"Travel words",s:"Vocabulary",qs:[
      {q:"'die Fahrkarte' is…",opts:["the ticket","the timetable","the platform","the seat"],a:0,ex:"'die Fahrkarte' is the ticket for a train or bus; the timetable is 'der Fahrplan'."},
      {q:"What does 'Der Zug hat Verspätung' mean?",opts:["The train is delayed.","The train is cancelled.","The train is full.","The train is early."],a:0,ex:"'die Verspätung' = delay; 'Verspätung haben' = to be late."},
      {q:"Which word means 'platform' (track number) at a station?",opts:["das Gleis","der Ausgang","die Abfahrt","der Fahrplan"],a:0,ex:"'das Gleis' is the track/platform number: Der Zug fährt von Gleis 5."}
    ]},
    {t:"Email & hotel phrases",s:"Vocabulary",qs:[
      {q:"'ein Zimmer reservieren' means…",opts:["to book a room","to clean a room","to leave a room","to pay for a room"],a:0,ex:"'reservieren' = to reserve or book in advance."},
      {q:"'umsteigen' means…",opts:["to change trains","to get off","to get on","to miss a train"],a:0,ex:"'umsteigen' = change; einsteigen = get on, aussteigen = get off."},
      {q:"Which of these is an informal email closing?",opts:["Viele Grüße","Mit freundlichen Grüßen","Sehr geehrter Herr Braun","Hochachtungsvoll"],a:0,ex:"'Viele Grüße' is friendly and informal; 'Mit freundlichen Grüßen' is the formal standard."}
    ]},
    {t:"Station sounds",s:"Pronunciation",qs:[
      {q:"Listen. How is 'sp' in 'Verspätung' pronounced?",say:"Verspätung",opts:["like 'shp'","like 'sp' in 'spot'","like 'zp'","like 'sb'"],a:0,ex:"At the start of a word stem, sp is pronounced 'shp' (spät, Verspätung)."},
      {q:"Listen. Which station word do you hear?",say:"Gleis",opts:["Gleis","Glas","gleich","Kreis"],a:0,ex:"'Gleis' starts with gl and has ei (like 'eye') and ends in a sharp s."},
      {q:"Listen. How is 'ß' in 'Grüße' pronounced?",say:"Viele Grüße",opts:["a sharp, hissing 's'","like 'b' in 'bed'","a buzzing 'z' as in 'zoo'","like 'sh' in 'shoe'"],a:0,ex:"ß is always a voiceless s, never a buzzing z; it appears after long vowels."}
    ]},
    {t:"Polite requests",s:"Grammar",qs:[
      {q:"Which form makes this request most polite? '___ Sie mir bitte helfen?'",opts:["Könnten","Kannst","Müssen","Wollen"],a:0,ex:"'Könnten Sie ...?' (could you) is the softest, most polite way to ask for help."},
      {q:"Complete: '___ Sie mir bitte die Rechnung schicken?'",opts:["Würden","Wurden","Wird","Würdest"],a:0,ex:"'Würden Sie ...?' (would you) + infinitive at the end makes a polite request; Sie needs 'würden'."},
      {q:"Choose the correct polite request.",opts:["Könnten Sie das Fenster öffnen?","Könnten Sie das Fenster öffnet?","Könnten Sie öffnen das Fenster?","Könnte Sie das Fenster öffnen?"],a:0,ex:"'Könnten' agrees with Sie, and the infinitive 'öffnen' goes to the end."}
    ]},
    {t:"Email openings",s:"Grammar",qs:[
      {q:"Complete the email: '___ Thomas,'",opts:["Lieber","Liebe","Lieben","Liebes"],a:0,ex:"For a man use 'Lieber', for a woman 'Liebe': Lieber Thomas, Liebe Anna."},
      {q:"Complete: 'Sehr ___ Frau Klein,'",opts:["geehrte","geehrter","geehrten","geehrtes"],a:0,ex:"For a woman it is 'Sehr geehrte Frau ...'; for a man 'Sehr geehrter Herr ...'."},
      {q:"Which formal opening is correct when you don't know the person's name?",opts:["Sehr geehrte Damen und Herren,","Sehr geehrter Damen und Herren,","Sehr geehrte Dame und Herr,","Sehr geehrten Damen und Herren,"],a:0,ex:"The fixed formula is 'Sehr geehrte Damen und Herren,' (plural, ending -e)."}
    ]},
    {t:"Reading: emails & displays",s:"Reading",qs:[
      {q:"Read: 'Sehr geehrte Damen und Herren, ich möchte vom 3. bis 5. Mai ein Einzelzimmer reservieren. Ist das Frühstück inklusive?' What does the writer want?",opts:["a single room for two nights","a double room for three nights","breakfast without a room","to cancel a booking"],a:0,ex:"'Einzelzimmer' = single room; arriving on the 3rd and leaving on the 5th means two nights."},
      {q:"Read: 'Liebe Sara, danke für deine Mail! Ich komme am Freitag um 17 Uhr mit dem Zug an. Holst du mich ab? Viele Grüße, Ben' What does Ben ask?",opts:["if Sara can pick him up","if Sara can buy his ticket","if Sara is coming on Friday","if Sara's train is late"],a:0,ex:"'abholen' = to pick someone up; 'Holst du mich ab?' = Will you pick me up?"},
      {q:"Read the display: 'ICE 578 nach Köln – heute von Gleis 7 – ca. 20 Minuten später.' Which is true?",opts:["The train is about 20 minutes late.","The train leaves from platform 20.","The train is cancelled today.","The train goes to Bonn."],a:0,ex:"'ca. 20 Minuten später' = about 20 minutes later; the platform is 7."}
    ]},
    {t:"Listening: at the station",s:"Listening",qs:[
      {q:"Listen. What does the passenger want?",say:"Einmal nach Köln, bitte.",opts:["one ticket to Cologne","two tickets to Cologne","a ticket from Cologne","one ticket to Kiel"],a:0,ex:"'Einmal nach ...' is the short way to ask for one ticket to a place; Köln = Cologne."},
      {q:"Listen. Which platform does the train leave from?",say:"Der Zug nach München fährt heute von Gleis neun.",opts:["platform 9","platform 19","platform 5","platform 7"],a:0,ex:"'Gleis neun' = platform 9; neunzehn would be 19."},
      {q:"Listen. What must you do in Frankfurt?",say:"Sie müssen in Frankfurt umsteigen.",opts:["change trains","get off and stay","buy a new ticket","wait an hour"],a:0,ex:"'umsteigen' = to change (trains, buses)."}
    ]},
    {t:"At the station & hotel",s:"Speaking",qs:[
      {q:"At the ticket counter you want a return ticket to Hamburg. What do you say?",opts:["Eine Rückfahrkarte nach Hamburg, bitte.","Eine Rückfahrkarte zu Hamburg, bitte.","Eine Rückfahrkarte in Hamburg, bitte.","Eine Rückfahrkarte bei Hamburg, bitte."],a:0,ex:"Cities and countries without an article take 'nach' for direction: nach Hamburg."},
      {q:"At the hotel your room is too noisy. How do you ask politely for another one?",opts:["Könnten Sie mir ein anderes Zimmer geben?","Geben Sie mir sofort ein anderes Zimmer!","Ich muss jetzt ein anderes Zimmer haben.","Sie dürfen mir ein anderes Zimmer geben."],a:0,ex:"'Könnten Sie ...?' turns the request into a polite question instead of a demand."},
      {q:"An announcement says your train is delayed. You ask staff:",opts:["Wie lange hat der Zug Verspätung?","Wie lange ist der Zug Verspätung?","Wie viel hat der Zug spät?","Wann hat der Zug Verspätung gehabt?"],a:0,ex:"The fixed expression is 'Verspätung haben', so you ask 'Wie lange hat der Zug Verspätung?'."}
    ]},
    {t:"Writing emails",s:"Writing",qs:[
      {q:"Which formal email sign-off is spelled correctly?",opts:["Mit freundlichen Grüßen","Mit freundliche Grüße","Mit freundlichen Grüße","Mit freundlicher Grüßen"],a:0,ex:"'mit' takes the dative plural, so adjective and noun both end in -n: freundlichen Grüßen."},
      {q:"Fill the gap: 'Ich schreibe Ihnen ___ meiner Reservierung.'",opts:["wegen","weil","deshalb","denn"],a:0,ex:"'wegen' is a preposition used before a noun (regarding); weil and denn introduce clauses."},
      {q:"Choose the correct sentence for an email to a hotel.",opts:["Ich möchte ein Zimmer für zwei Nächte reservieren.","Ich möchte reservieren ein Zimmer für zwei Nächte.","Ich möchte ein Zimmer für zwei Nacht reservieren.","Ich möchte ein Zimmer für zwei Nächte reserviere."],a:0,ex:"After 'möchte' the infinitive goes to the end, and the plural of Nacht is Nächte."}
    ]},
    {t:"Register & travel culture",s:"Culture",qs:[
      {q:"You write to a landlord, Mr Wagner, whom you don't know personally. Which opening fits?",opts:["Sehr geehrter Herr Wagner,","Hi Wagner,","Lieber Wagner,","Hey Herr Wagner!"],a:0,ex:"With people you address as Sie in a first contact, 'Sehr geehrter Herr ...' is the safe, formal choice."},
      {q:"What is the 'BahnCard' in Germany?",opts:["a discount card for train travel","a map of the city's tram lines","a ticket for the platform","a printed train timetable"],a:0,ex:"The BahnCard gives regular rail travellers a percentage off German train tickets."},
      {q:"In a German email after 'Liebe Anna,' the first word of the next line…",opts:["starts lower case unless it's a noun","always starts with a capital letter","must always be 'Hallo'","is always written in bold"],a:0,ex:"The comma after the greeting means the text continues the sentence, so it starts in lower case."}
    ]},
    {t:"Review: emails & travel",s:"Review",qs:[
      {q:"Which pair is a formal opening + formal closing?",opts:["Sehr geehrte Frau Klein … Mit freundlichen Grüßen","Liebe Frau Klein … Tschüss und bis bald","Hallo Frau Klein … Viele liebe Grüße","Sehr geehrte Frau Klein … Bis später"],a:0,ex:"Formal emails start with 'Sehr geehrte(r)' and end with 'Mit freundlichen Grüßen'."},
      {q:"What does 'Ich schreibe wegen ...' mean?",opts:["I'm writing regarding ...","I'm writing on the way ...","I'm writing once more ...","I'm writing to say no ..."],a:0,ex:"'wegen' = because of / regarding; it introduces the reason for the email."},
      {q:"Complete: 'Der Zug ___ zehn Minuten Verspätung.'",opts:["hat","ist","macht","gibt"],a:0,ex:"In German a train 'has' a delay: Verspätung haben."}
    ]},
    {t:"Travel German under pressure",s:"Challenge",qs:[
      {q:"Complete: 'Wann fährt der nächste Zug ___ Berlin?'",opts:["nach","zu","in","bei"],a:0,ex:"For travelling to a city (without an article), German uses 'nach'."},
      {q:"Which request is the most polite and correct?",opts:["Würden Sie mir bitte sagen, wann der Zug fährt?","Sagen Sie mir sofort, wann der Zug fährt!","Können Sie mir sagen, wann fährt der Zug?","Du sagst mir bitte, wann der Zug fährt."],a:0,ex:"'Würden Sie ...?' is polite, and in the indirect question 'wann ...' the verb goes to the end."},
      {q:"Complete: 'Ich muss in Mannheim ___.'",opts:["umsteigen","umgestiegen","steige um","umsteige"],a:0,ex:"After the modal 'muss' the separable verb stays together as an infinitive at the end."}
    ]}
  ],
  // Module 6: Comparisons, Health & the Body
  [
    {t:"Body parts",s:"Vocabulary",qs:[
      {q:"'der Kopf' is…",opts:["the head","the neck","the back","the stomach"],a:0,ex:"'der Kopf' = the head, as in Kopfschmerzen (headache)."},
      {q:"Which word means 'back' as a body part?",opts:["der Rücken","der Bauch","der Arm","das Knie"],a:0,ex:"'der Rücken' = the back; der Bauch is the stomach/belly."},
      {q:"What is 'die Apotheke'?",opts:["the pharmacy","the hospital","the doctor's office","the bakery"],a:0,ex:"In a German Apotheke you buy medicine; the hospital is 'das Krankenhaus'."}
    ]},
    {t:"Comparing & symptoms",s:"Vocabulary",qs:[
      {q:"'am besten' means…",opts:["best","better","good","most"],a:0,ex:"gut – besser – am besten: good, better, best."},
      {q:"What is the opposite of 'größer'?",opts:["kleiner","langsamer","älter","schlechter"],a:0,ex:"'größer' = bigger/taller, so the opposite comparative is 'kleiner' (smaller)."},
      {q:"'Ich habe Fieber' means…",opts:["I have a temperature.","I have a cough.","I have a cold.","I have a headache."],a:0,ex:"'das Fieber' = fever; cough is 'der Husten', headache 'Kopfschmerzen'."}
    ]},
    {t:"Umlauts in comparisons",s:"Pronunciation",qs:[
      {q:"Listen carefully. Which of these words is spoken?",say:"älter",opts:["älter","alter","Eltern","elfter"],a:0,ex:"'älter' starts with ä (like e in 'bed'), not the a of 'alter'."},
      {q:"Listen. How is the 'ö' in 'größer' pronounced?",say:"größer",opts:["like 'e' said with rounded lips","like 'o' in 'hot'","like 'oo' in 'food'","like 'a' in 'father'"],a:0,ex:"For ö, say an e sound and round your lips; in größer it is long."},
      {q:"Listen. Which body part do you hear?",say:"der Bauch",opts:["der Bauch","der Brauch","das Buch","der Bach"],a:0,ex:"'Bauch' has au (like 'ow') and ends in the throaty ach sound."}
    ]},
    {t:"Comparative + als",s:"Grammar",qs:[
      {q:"Complete with 'alt': 'Mein Bruder ist ___ als ich.'",opts:["älter","alter","mehr alt","ältest"],a:0,ex:"Short adjectives often add an umlaut in the comparative: alt – älter."},
      {q:"Complete: 'Berlin ist größer ___ Bonn.'",opts:["als","wie","so","dann"],a:0,ex:"After a comparative, German uses 'als' (than) for unequal things."},
      {q:"What is the comparative of 'gut'?",opts:["besser","guter","güter","mehr gut"],a:0,ex:"'gut' is irregular: gut – besser – am besten."}
    ]},
    {t:"so ... wie & superlatives",s:"Grammar",qs:[
      {q:"Complete: 'Sie ist so alt ___ ich.'",opts:["wie","als","so","wenn"],a:0,ex:"For equal things use 'so ... wie' (as ... as); 'als' only follows a comparative."},
      {q:"Which superlative form is correct?",opts:["am schnellsten","am schnellste","am schnellen","an schnellsten"],a:0,ex:"The adverbial superlative is 'am' + adjective + -sten."},
      {q:"Complete: 'Ich trinke Tee gern, aber Kaffee trinke ich ___.'",opts:["lieber","gerner","mehr gern","besser"],a:0,ex:"'gern' is irregular: gern – lieber – am liebsten (like – prefer – like most)."}
    ]},
    {t:"Reading: health & heights",s:"Reading",qs:[
      {q:"Read: 'Mir tut seit zwei Tagen der Rücken weh. Ich kann nicht gut schlafen.' What is the problem?",opts:["back pain for two days","a headache for two days","stomach ache since yesterday","a cold for two weeks"],a:0,ex:"'der Rücken' = the back, and 'seit zwei Tagen' = for two days."},
      {q:"Read: 'Der Arzt sagt: Sie sollen viel trinken und im Bett bleiben.' What should the patient do?",opts:["drink a lot and stay in bed","eat a lot and go for walks","drink less and work more","sleep less and drink tea"],a:0,ex:"'viel trinken' = drink a lot, 'im Bett bleiben' = stay in bed; sollen passes on the advice."},
      {q:"Read: 'Lisa ist 1,70 m groß, Tom ist 1,80 m und Max ist 1,75 m.' Who is the tallest?",opts:["Tom","Lisa","Max","Lisa and Max"],a:0,ex:"1.80 m is the greatest height, so Tom ist am größten."}
    ]},
    {t:"Listening: at the doctor's",s:"Listening",qs:[
      {q:"Listen. What are the symptoms?",say:"Mir tut der Hals weh und ich habe Husten.",opts:["sore throat and a cough","headache and a cough","sore throat and a fever","earache and a cold"],a:0,ex:"'der Hals' = the throat, and 'der Husten' = cough."},
      {q:"Listen. Who is older?",say:"Ich bin zwei Jahre älter als meine Schwester.",opts:["the speaker","the sister","both are the same age","the brother"],a:0,ex:"'Ich bin älter als ...' = I am older than ...; the speaker is two years older."},
      {q:"Listen. Until when is the pharmacy open?",say:"Die Apotheke ist bis achtzehn Uhr geöffnet.",opts:["until 6 p.m.","until 8 p.m.","until 8 a.m.","until 10 p.m."],a:0,ex:"'achtzehn Uhr' = 18:00 on the 24-hour clock, i.e. 6 p.m."}
    ]},
    {t:"Describing symptoms",s:"Speaking",qs:[
      {q:"The doctor asks: 'Was fehlt Ihnen?' What is the best reply?",opts:["Ich habe Kopfschmerzen.","Ich bin Kopfschmerzen.","Mich tut der Kopf.","Ich fehle den Kopf."],a:0,ex:"'Was fehlt Ihnen?' = What's wrong? You answer with 'Ich habe' + symptom."},
      {q:"Your feet hurt. What do you say?",opts:["Mir tun die Füße weh.","Mir tut die Füße weh.","Ich tue die Füße weh.","Mich tun die Füße weh."],a:0,ex:"The person is in the dative (mir), and the verb agrees with the plural 'die Füße': tun."},
      {q:"You phone the doctor's office for an appointment. What do you say?",opts:["Ich möchte gern einen Termin machen.","Ich möchte gern einen Termin gemacht.","Ich möchte gern ein Termin machen.","Ich möchte gern einen Termin machst."],a:0,ex:"der Termin is masculine, so the accusative is 'einen Termin', and the infinitive 'machen' goes last."}
    ]},
    {t:"Writing comparisons",s:"Writing",qs:[
      {q:"Comparing two cities: choose the correct sentence.",opts:["München ist größer als Köln.","München ist größer wie Köln.","München ist mehr groß als Köln.","München ist großer als Köln."],a:0,ex:"groß – größer takes an umlaut, and comparisons of inequality use 'als'."},
      {q:"Fill the gap: 'Das ist der ___ Zug.'",opts:["schnellste","schnellsten","am schnellsten","schneller als"],a:0,ex:"Before a noun the superlative works like an adjective: der schnellste Zug."},
      {q:"Comparing family members: which sentence is correct?",opts:["Meine Schwester ist so groß wie ich.","Meine Schwester ist so groß als ich.","Meine Schwester ist so größer wie ich.","Meine Schwester ist größer wie ich."],a:0,ex:"Equality: so + base adjective + wie; the comparative needs 'als' instead."}
    ]},
    {t:"Health culture",s:"Culture",qs:[
      {q:"In Germany, where do you normally buy painkillers like ibuprofen?",opts:["in the Apotheke","in the supermarket","at the petrol station","at the bakery"],a:0,ex:"Most medicines, even many non-prescription ones, are sold only in pharmacies in Germany."},
      {q:"You are ill for several days and can't go to work in Germany. What do you usually need?",opts:["a sick note from a doctor","a note from your neighbour","a receipt from the pharmacy","a letter from your bank"],a:0,ex:"Employers usually require a doctor's certificate (Krankschreibung) after a few days of illness."},
      {q:"Someone sneezes. What do people around them usually say?",opts:["Gesundheit!","Guten Appetit!","Prost!","Mahlzeit!"],a:0,ex:"'Gesundheit!' (health) is the usual response to a sneeze, like 'Bless you!'."}
    ]},
    {t:"Review: body & comparisons",s:"Review",qs:[
      {q:"Translate: 'My stomach hurts.'",opts:["Mir tut der Bauch weh.","Ich tue der Bauch weh.","Mir tut den Bauch weh.","Mir tun der Bauch weh."],a:0,ex:"Pattern: Mir tut + singular body part (nominative) + weh."},
      {q:"What is the comparative of 'viel'?",opts:["mehr","vieler","meist","mehrer"],a:0,ex:"'viel' is irregular: viel – mehr – am meisten."},
      {q:"Which word is NOT a part of the body?",opts:["der Kopf","der Rücken","der Bauch","die Ampel"],a:3,ex:"'die Ampel' is a traffic light; the others are parts of the body."}
    ]},
    {t:"Superlatives & pain",s:"Challenge",qs:[
      {q:"Complete: 'Von allen Städten gefällt mir Hamburg ___.'",opts:["am besten","besser","am gutesten","bester"],a:0,ex:"Comparing with all others needs the superlative, and gut is irregular: am besten."},
      {q:"Complete: 'Mir ___ die Augen weh.'",opts:["tun","tut","tue","tust"],a:0,ex:"The subject is the plural 'die Augen', so the verb is plural: tun."},
      {q:"Which sentence about running is correct?",opts:["Er läuft schneller als sein Bruder.","Er läuft schneller wie sein Bruder.","Er läuft mehr schnell als sein Bruder.","Er läuft am schneller als sein Bruder."],a:0,ex:"Comparative = adjective + -er (no 'mehr'), followed by 'als' for the thing compared."}
    ]}
  ]
];
